pub fn play_queued_sounds(mut commands: Commands, project_path: Res<ProjectPath>, asset_server: Res<AssetServer>, mut sound_queue: ResMut<SoundQueue>, playing_query: Query<(Entity, &PlayingSound)>) -> () {
    if sound_queue.stop_all_requested {
        for (entity, marker) in playing_query.into_iter() {
            commands.entity(entity).despawn();
        }
        sound_queue.stop_all_requested = false;
    }
    let requests = sound_queue.play_queue.clone();
    sound_queue.play_queue = vec![];
    for request in requests.iter().cloned() {
        let volume = request.volume.clone();
        let rate = ((2.0 as f64).powf((request.pitch / 120.0) as f64) as f32);
        if let Some(sound_path) = extract_sound_to_temp_file(Arc::<str>::from(project_path.path.clone().to_string()), Arc::<str>::from(request.target_id.to_string()), Arc::<str>::from(request.sound_name.to_string())) {
            let handle: Handle<AudioSource> = asset_server.load(sound_path.to_string());
            let base_settings = PlaybackSettings::DESPAWN.clone();
            let with_volume = base_settings.with_volume(Volume::Linear((volume / 100.0)));
            let settings = with_volume.with_speed(rate);
            if (request.pan == 0.0) {
                commands.spawn((PlayingSound {}, AudioPlayer(handle), settings));
            } else {
                let mut spatial_settings = settings;
                spatial_settings.spatial = true;
                let offset = ((request.pan / 100.0) * 0.9);
                commands.spawn((PlayingSound {}, AudioPlayer(handle), spatial_settings, Transform::from_xyz(offset, 0.0, 0.0)));
            }
        }
    }
}

pub fn spawn_pending_clones(mut commands: Commands, mut sound_queue: ResMut<SoundQueue>, start_as_clone_hats: Res<StartAsCloneHats>, mut pending: ResMut<PendingThreads>, sprites: Query<(&ScratchSprite, &TargetCostumeHandles, &Sprite, &Transform)>) -> () {
    let requests = sound_queue.clone_requests.clone();
    sound_queue.clone_requests = vec![];
    for request in requests.iter().cloned() {
        for (sprite, handles, spr, transform) in sprites.into_iter() {
            if (sprite.target_id == request.origin_name) {
                let mut clone_root = commands.spawn((ScratchSprite { target_id: Arc::<str>::from(request.new_id.clone().to_string()) }, spr.clone(), handles.clone(), transform.clone()));
                clone_root.with_children(|parent| drop(parent.spawn((SpeechBubbleAnchor { target_id: Arc::<str>::from(request.new_id.clone().to_string()) }, Text2d::new(""), Anchor(Vec2::new(0.0, (-1.0))), Transform::from_xyz(0.0, 0.0, 1.0)))));
                break;
            }
        }
        for template in start_as_clone_hats.get(request.origin_name.clone()).into_iter() {
            let script: ReceiverScript = ReceiverScript { target_id: Arc::<str>::from(request.new_id.clone().to_string()), body: template.body.clone() };
            pending.queue.push(spawn_thread(script.clone()));
        }
    }
}

pub fn despawn_pending_clones(mut commands: Commands, mut sound_queue: ResMut<SoundQueue>, mut positions: ResMut<Positions>, mut looks: ResMut<LooksStates>, mut layer_orders: ResMut<LayerOrders>, mut speech_bubbles: ResMut<SpeechBubbles>, mut vars: ResMut<Vars>, mut lists: ResMut<Lists>, sprites: Query<(Entity, &ScratchSprite)>) -> () {
    let requests = sound_queue.despawn_requests.clone();
    sound_queue.despawn_requests = vec![];
    for instance_id in requests.iter().cloned() {
        for (entity, sprite) in sprites.into_iter() {
            if (sprite.target_id == instance_id) {
                commands.entity(entity).despawn();
                break;
            }
        }
        positions.remove(instance_id.clone());
        looks.remove(instance_id.clone());
        layer_orders.remove(instance_id.clone());
        sound_queue.remove_volume(instance_id.clone());
        sound_queue.remove_pitch(instance_id.clone());
        sound_queue.remove_pan(instance_id.clone());
        sound_queue.remove_rotation_style(instance_id.clone());
        sound_queue.remove_draggable(instance_id.clone());
        sound_queue.remove_pen_state(instance_id.clone());
        sound_queue.remove_instance_type(instance_id.clone());
        vars.remove_local(instance_id.clone());
        lists.remove_local(instance_id.clone());
        speech_bubbles.remove(instance_id);
    }
}

pub fn sync_speech_bubbles(query: Query<(&SpeechBubbleAnchor, &mut Text2d, &mut Transform)>, speech_bubbles: Res<SpeechBubbles>, looks: Res<LooksStates>, costume_dims: Res<TargetCostumeDims>, sound_queue: Res<SoundQueue>) -> () {
    for (anchor, mut text2d, mut transform) in query.into_iter() {
        let text = speech_bubbles.text_for(anchor.target_id.clone());
        *text2d = Text2d::new(Arc::<str>::from(format!("{}", text).as_str()).to_string());
        let s = looks.get(anchor.target_id.clone());
        let origin = sound_queue.instance_type_of(anchor.target_id.clone());
        let idx = s.costume_index.clone();
        let dim = costume_dims.get(origin.clone(), idx.clone());
        let scale = (s.size / 100.0);
        let hh = ((dim.height * scale) / 2.0);
        transform.translation.y = (hh + 10.0);
    }
}

pub fn sync_variable_watchers(query: Query<(&VariableWatcherTag, &mut Text2d, &mut Visibility)>, vars: Res<Vars>) -> () {
    for (tag, mut text2d, mut visibility) in query.into_iter() {
        let value = vars.get(tag.variable_id.clone(), vars.owner_of(tag.variable_id.clone()));
        *text2d = Text2d::new(Arc::<str>::from(format!("{}: {}", tag.label, value).as_str()).to_string());
        *visibility = {
        if vars.watcher_shown(tag.variable_id.clone()) {
            Visibility::Visible
        } else {
            Visibility::Hidden
        }
};
    }
}

pub fn sync_reporter_watchers(query: Query<(&ReporterWatcherTag, &mut Text2d)>, mut vars: ResMut<Vars>, mut lists: ResMut<Lists>, procs: Res<ProcTable>, broadcasts: Res<Broadcasts>, mut positions: ResMut<Positions>, keyboard: Res<KeyboardState>, mouse: Res<MouseState>, timer: Res<ScratchTimer>, mut rng: ResMut<Rng>, mut looks: ResMut<LooksStates>, target_costumes: Res<TargetCostumes>, costume_dims: Res<TargetCostumeDims>, sound_queue: Res<SoundQueue>) -> () {
    for (tag, mut text2d) in query.into_iter() {
        let top_frame: Frame = Frame { params: HashMap::new(), target_id: Arc::<str>::from(tag.target_id.clone().to_string()) };
        let value = eval(tag.expr.clone(), &mut *vars, top_frame.clone(), procs.clone(), &mut *lists, broadcasts.clone(), &mut *positions, keyboard.clone(), &mouse, &timer, &mut *rng, &mut *looks, target_costumes.clone(), costume_dims.clone(), sound_queue.clone());
        *text2d = Text2d::new(Arc::<str>::from(format!("{}: {}", tag.label, value).as_str()).to_string());
    }
}

pub fn sync_list_watchers(query: Query<(&ListWatcherTag, &mut Text2d, &mut Visibility)>, lists: Res<Lists>) -> () {
    for (tag, mut text2d, mut visibility) in query.into_iter() {
        let contents = list_watcher_display_string(lists.clone(), Arc::<str>::from(tag.list_id.clone().to_string()));
        *visibility = {
        if lists.watcher_shown(tag.list_id.clone()) {
            Visibility::Visible
        } else {
            Visibility::Hidden
        }
};
        *text2d = Text2d::new(Arc::<str>::from(format!("{}\n{}", tag.label, contents).as_str()).to_string());
    }
}

pub fn sync_ask_ui(query: Query<(&AskBoxText, &mut Text2d, &mut Visibility)>, vars: Res<Vars>) -> () {
    for (tag, mut text2d, mut visibility) in query.into_iter() {
        if vars.is_asking() {
            *visibility = Visibility::Visible;
            let mut question: Arc<str> = Arc::<str>::from("");
            if let Some(ask) = vars.front_ask() {
                question = ask.question;
            }
            *text2d = Text2d::new(Arc::<str>::from(format!("{}\n{}|", question, vars.ask_buffer).as_str()).to_string());
        } else {
            *visibility = Visibility::Hidden;
            *text2d = Text2d::new("");
        }
    }
}

pub fn handle_ask_text_input(mut events: MessageReader<KeyboardInput>, mut vars: ResMut<Vars>) -> () {
    for event in events.read().into_iter() {
        if ((event.state == ButtonState::Pressed) && vars.is_asking()) {
            if (event.key_code == KeyCode::Enter) {
                if let Some(ask) = vars.front_ask() {
                    let submitted = vars.ask_buffer.clone();
                    vars.set_answer(submitted);
                    vars.last_answered_id = ask.ask_id;
                    let mut remaining = vars.ask_queue.clone();
                    remaining.remove({ let __boring_idx = 0 as i64; if __boring_idx < 0 { (remaining.len() as i64 + __boring_idx) as usize } else { __boring_idx as usize } });
                    vars.ask_queue = remaining;
                    vars.ask_buffer = Arc::<str>::from("");
                }
            } else if (event.key_code == KeyCode::Backspace) {
                let mut chars = vars.ask_buffer.chars().map(|c| Arc::<str>::from(c.to_string())).collect::<Vec<Arc<str>>>();
                chars.pop().unwrap_or_default();
                let mut rebuilt: Arc<str> = Arc::<str>::from("");
                for c in chars.iter().cloned() {
                    rebuilt = Arc::<str>::from(Arc::<str>::from(format!("{}{}", rebuilt, c).as_str()));
                }
                vars.ask_buffer = rebuilt.clone();
            } else {
                if let Some(typed) = event.text.clone() {
                    vars.ask_buffer = Arc::<str>::from(Arc::<str>::from(format!("{}{}", vars.ask_buffer, typed).as_str()));
                }
            }
        }
    }
}

