pub fn sync_mouse_state(mut state: ResMut<MouseState>, window: Single<&Window>, mouse_buttons: Res<ButtonInput<MouseButton>>) -> () {
    state.down = mouse_buttons.pressed(MouseButton::Left);
    if let Some(pos) = window.cursor_position() {
        state.x = (pos.x - (window.width() / 2.0));
        state.y = ((window.height() / 2.0) - pos.y);
    }
}

pub fn sync_scratch_timer(mut timer: ResMut<ScratchTimer>, time: Res<Time>, mut sound_queue: ResMut<SoundQueue>) -> () {
    if sound_queue.reset_timer_requested {
        timer.elapsed = 0.0;
        sound_queue.reset_timer_requested = false;
    } else {
        timer.elapsed += time.delta_secs();
    }
}

pub fn check_key_press_hats(keyboard: Res<ButtonInput<KeyCode>>, key_press_hats: Res<KeyPressHats>, sound_queue: Res<SoundQueue>, vars: Res<Vars>, mut pending: ResMut<PendingThreads>) -> () {
    if (!vars.is_asking()) {
        for hat in key_press_hats.hats.clone().into_iter() {
            if key_option_just_pressed(keyboard.clone(), Arc::<str>::from(hat.key_option.to_string())) {
                for instance_id in instances_of(&sound_queue.instance_types, Arc::<str>::from(hat.script.target_id.clone().to_string())).into_iter() {
                    let script: ReceiverScript = ReceiverScript { target_id: Arc::<str>::from(instance_id.to_string()), body: hat.script.body.clone() };
                    pending.queue.push(spawn_thread(script.clone()));
                }
            }
        }
    }
}

pub fn check_click_hats(mouse_buttons: Res<ButtonInput<MouseButton>>, mouse: Res<MouseState>, click_hats: Res<ClickHats>, positions: Res<Positions>, looks: Res<LooksStates>, costume_dims: Res<TargetCostumeDims>, sound_queue: Res<SoundQueue>, mut pending: ResMut<PendingThreads>) -> () {
    if mouse_buttons.just_pressed(MouseButton::Left) {
        for hat in click_hats.hats.clone().into_iter() {
            let origin_name = hat.script.target_id.clone();
            if (origin_name == Arc::<str>::from("Stage")) {
                if ((((mouse.x >= (-240.0)) && (mouse.x <= 240.0)) && (mouse.y >= (-180.0))) && (mouse.y <= 180.0)) {
                    let script: ReceiverScript = ReceiverScript { target_id: Arc::<str>::from("Stage"), body: hat.script.body.clone() };
                    pending.queue.push(spawn_thread(script.clone()));
                }
            } else {
                for instance_id in instances_of(&sound_queue.instance_types, Arc::<str>::from(origin_name.clone().to_string())).into_iter() {
                    let s = looks.get(instance_id.clone());
                    if s.visible {
                        let pos = positions.get(instance_id.clone());
                        let dim = costume_dims.get(origin_name.clone(), s.costume_index);
                        let scale = (s.size / 100.0);
                        let half_w = ((dim.width * scale) / 2.0);
                        let half_h = ((dim.height * scale) / 2.0);
                        if touching_point(pos.x.clone(), pos.y.clone(), half_w, half_h, mouse.x.clone(), mouse.y.clone()) {
                            let script: ReceiverScript = ReceiverScript { target_id: Arc::<str>::from(instance_id.to_string()), body: hat.script.body.clone() };
                            pending.queue.push(spawn_thread(script.clone()));
                        }
                    }
                }
            }
        }
    }
}

pub fn handle_sprite_dragging(mouse_buttons: Res<ButtonInput<MouseButton>>, mouse: Res<MouseState>, sound_queue: Res<SoundQueue>, looks: Res<LooksStates>, costume_dims: Res<TargetCostumeDims>, layer_orders: Res<LayerOrders>, mut positions: ResMut<Positions>, mut drag_state: ResMut<DragState>) -> () {
    if mouse_buttons.just_pressed(MouseButton::Left) {
        let instance_types: HashMap<Arc<str>, Arc<str>> = sound_queue.instance_types.clone();
        let draggable_now: HashMap<Arc<str>, bool> = sound_queue.draggable.clone();
        let mut best_id: Arc<str> = Arc::<str>::from("");
        let mut best_order = 0;
        let mut found = false;
        for (id, origin_name) in instance_types.into_iter() {
            let is_draggable = draggable_now.get(&id.clone()).cloned().unwrap_or_else(|| false);
            if is_draggable {
                let s = looks.get(id.clone());
                if s.visible {
                    let pos = positions.get(id.clone());
                    let dim = costume_dims.get(origin_name.clone(), s.costume_index);
                    let scale = (s.size / 100.0);
                    let half_w = ((dim.width * scale) / 2.0);
                    let half_h = ((dim.height * scale) / 2.0);
                    if touching_point(pos.x.clone(), pos.y.clone(), half_w, half_h, mouse.x.clone(), mouse.y.clone()) {
                        let order = layer_orders.get(id.clone());
                        if ((!found) || (order > best_order)) {
                            best_id = id;
                            best_order = order.clone();
                            found = true;
                        }
                    }
                }
            }
        }
        if found {
            let pos = positions.get(best_id.clone());
            drag_state.dragging_id = best_id.clone();
            drag_state.offset_x = (pos.x - mouse.x);
            drag_state.offset_y = (pos.y - mouse.y);
        }
    }
    if (drag_state.dragging_id != Arc::<str>::from("")) {
        if (mouse_buttons.pressed(MouseButton::Left) && sound_queue.get_draggable(drag_state.dragging_id.clone())) {
            let current = positions.get(drag_state.dragging_id.clone());
            positions.set(drag_state.dragging_id.clone(), Position { x: (mouse.x + drag_state.offset_x), y: (mouse.y + drag_state.offset_y), direction: current.direction });
        } else {
            drag_state.dragging_id = Arc::<str>::from("");
        }
    }
}

pub fn check_greater_than_hats(mut vars: ResMut<Vars>, mut lists: ResMut<Lists>, procs: Res<ProcTable>, broadcasts: Res<Broadcasts>, mut positions: ResMut<Positions>, keyboard: Res<KeyboardState>, mouse: Res<MouseState>, timer: Res<ScratchTimer>, mut rng: ResMut<Rng>, mut looks: ResMut<LooksStates>, target_costumes: Res<TargetCostumes>, costume_dims: Res<TargetCostumeDims>, sound_queue: Res<SoundQueue>, mut greater_than_hats: ResMut<GreaterThanHats>, mut pending: ResMut<PendingThreads>) -> () {
    let hats = greater_than_hats.hats.clone();
    let mut new_hats = vec![];
    for hat in hats.iter().cloned() {
        let is_true = {
        if (hat.menu == Arc::<str>::from("TIMER")) {
            let top_frame: Frame = Frame { params: HashMap::new(), target_id: Arc::<str>::from(hat.script.target_id.clone().to_string()) };
            let threshold = eval(hat.value_expr.clone(), &mut *vars, top_frame.clone(), procs.clone(), &mut *lists, broadcasts.clone(), &mut *positions, keyboard.clone(), &mouse, &timer, &mut *rng, &mut *looks, target_costumes.clone(), costume_dims.clone(), sound_queue.clone()).to_num();
            ScratchNumber::from_f32(timer.elapsed).gt_owned(threshold)
        } else if (hat.menu == Arc::<str>::from("LOUDNESS")) {
            let top_frame: Frame = Frame { params: HashMap::new(), target_id: Arc::<str>::from(hat.script.target_id.clone().to_string()) };
            let threshold = eval(hat.value_expr.clone(), &mut *vars, top_frame.clone(), procs.clone(), &mut *lists, broadcasts.clone(), &mut *positions, keyboard.clone(), &mouse, &timer, &mut *rng, &mut *looks, target_costumes.clone(), costume_dims.clone(), sound_queue.clone()).to_num();
            ScratchNumber::from_f32(current_loudness()).gt_owned(threshold)
        } else {
            false
        }
};
        if (is_true && (!hat.was_true)) {
            for instance_id in instances_of(&sound_queue.instance_types, Arc::<str>::from(hat.script.target_id.clone().to_string())).into_iter() {
                let script: ReceiverScript = ReceiverScript { target_id: Arc::<str>::from(instance_id.to_string()), body: hat.script.body.clone() };
                pending.queue.push(spawn_thread(script.clone()));
            }
        }
        new_hats.push(GreaterThanHat { menu: Arc::<str>::from(hat.menu.to_string()), value_expr: hat.value_expr, was_true: is_true, script: hat.script });
    }
    greater_than_hats.hats = new_hats;
}

pub fn check_touching_object_hats(mut vars: ResMut<Vars>, mut lists: ResMut<Lists>, procs: Res<ProcTable>, broadcasts: Res<Broadcasts>, mut positions: ResMut<Positions>, keyboard: Res<KeyboardState>, mouse: Res<MouseState>, timer: Res<ScratchTimer>, mut rng: ResMut<Rng>, mut looks: ResMut<LooksStates>, target_costumes: Res<TargetCostumes>, costume_dims: Res<TargetCostumeDims>, sound_queue: Res<SoundQueue>, mut touching_hats: ResMut<TouchingObjectHats>, mut pending: ResMut<PendingThreads>) -> () {
    let hats = touching_hats.hats.clone();
    let mut new_hats = vec![];
    for hat in hats.iter().cloned() {
        let mut new_was_true = HashMap::new();
        let was_true_by_instance: HashMap<Arc<str>, bool> = hat.was_true_by_instance.clone();
        for instance_id in instances_of(&sound_queue.instance_types, Arc::<str>::from(hat.script.target_id.clone().to_string())).into_iter() {
            let top_frame: Frame = Frame { params: HashMap::new(), target_id: Arc::<str>::from(instance_id.clone().to_string()) };
            let is_touching = eval(hat.touching_block.clone(), &mut *vars, top_frame.clone(), procs.clone(), &mut *lists, broadcasts.clone(), &mut *positions, keyboard.clone(), &mouse, &timer, &mut *rng, &mut *looks, target_costumes.clone(), costume_dims.clone(), sound_queue.clone()).truthy();
            let was_true = was_true_by_instance.get(&instance_id.clone()).cloned().unwrap_or_else(|| false);
            if (is_touching && (!was_true)) {
                let script: ReceiverScript = ReceiverScript { target_id: Arc::<str>::from(instance_id.clone().to_string()), body: hat.script.body.clone() };
                pending.queue.push(spawn_thread(script.clone()));
            }
            new_was_true.insert(instance_id.clone(), is_touching.clone());
        }
        new_hats.push(TouchingObjectHat { touching_block: hat.touching_block, was_true_by_instance: new_was_true, script: hat.script });
    }
    touching_hats.hats = new_hats;
}

pub fn check_backdrop_switch_hats(mut backdrop_hats: ResMut<BackdropSwitchHats>, looks: Res<LooksStates>, target_costumes: Res<TargetCostumes>, sound_queue: Res<SoundQueue>, mut pending: ResMut<PendingThreads>) -> () {
    let idx = looks.get(Arc::<str>::from("Stage")).costume_index.clone();
    let names = target_costumes.get(Arc::<str>::from("Stage"));
    let current_name = {
    if ((idx >= 0) && (idx < (names.len() as isize))) {
        names[(idx) as usize].clone()
    } else {
        Arc::<str>::from("")
    }
};
    if (current_name != backdrop_hats.last_backdrop_name) {
        backdrop_hats.last_backdrop_name = current_name.clone();
        let hats = backdrop_hats.hats.clone();
        for hat in hats.iter().cloned() {
            if (hat.backdrop_name == current_name) {
                for instance_id in instances_of(&sound_queue.instance_types, Arc::<str>::from(hat.script.target_id.clone().to_string())).into_iter() {
                    let script: ReceiverScript = ReceiverScript { target_id: Arc::<str>::from(instance_id.to_string()), body: hat.script.body.clone() };
                    pending.queue.push(spawn_thread(script.clone()));
                }
            }
        }
    }
}

pub fn sync_transforms_from_positions(query: Query<(&mut Transform, &mut Sprite, &ScratchSprite)>, positions: Res<Positions>, sound_queue: Res<SoundQueue>) -> () {
    for (mut transform, mut sprite, scratch_sprite) in query.into_iter() {
        let p = positions.get(scratch_sprite.target_id.clone());
        transform.translation.x = p.x;
        transform.translation.y = p.y;
        let style = sound_queue.get_rotation_style(scratch_sprite.target_id.clone());
        if (style == Arc::<str>::from("all around")) {
            let radians = ((90.0 - p.direction) * 0.017453292);
            transform.rotation = Quat::from_rotation_z(radians);
            sprite.flip_x = false;
        } else {
            transform.rotation = Quat::from_rotation_z(0.0);
            if (style == Arc::<str>::from("left-right")) {
                sprite.flip_x = (p.direction < 0.0);
            } else {
                sprite.flip_x = false;
            }
        }
    }
}

pub fn sync_visibility_and_size_from_looks_states(query: Query<(&mut Visibility, &mut Transform, &ScratchSprite)>, looks: Res<LooksStates>) -> () {
    for (mut visibility, mut transform, sprite) in query.into_iter() {
        let s = looks.get(sprite.target_id.clone());
        *visibility = {
        if s.visible {
            Visibility::Visible
        } else {
            Visibility::Hidden
        }
};
        let scale = (s.size / 100.0);
        transform.scale.x = scale;
        transform.scale.y = scale;
    }
}

pub fn sync_costume_from_looks_states(query: Query<(&mut Sprite, &TargetCostumeHandles, &ScratchSprite)>, looks: Res<LooksStates>, costume_dims: Res<TargetCostumeDims>, sound_queue: Res<SoundQueue>) -> () {
    for (mut sprite, costumes, tag) in query.into_iter() {
        if ((costumes.handles.len() as isize) > 0) {
            let s = looks.get(tag.target_id.clone());
            let idx = wrap_costume_index(s.costume_index.clone(), (costumes.handles.len() as isize).clone());
            sprite.image = costumes.handles[(idx) as usize].clone().clone();
            let origin = sound_queue.instance_type_of(tag.target_id.clone());
            let dim = costume_dims.get(origin.clone(), idx.clone());
            let new_size: Option<Vec2> = Some(Vec2::new(dim.width, dim.height));
            sprite.custom_size = new_size;
        }
    }
}

pub fn sync_ghost_effect_from_looks_states(query: Query<(&mut Sprite, &ScratchSprite)>, looks: Res<LooksStates>) -> () {
    for (mut sprite, tag) in query.into_iter() {
        let s = looks.get(tag.target_id.clone());
        let alpha = (1.0 - (s.ghost / 100.0));
        sprite.color = sprite.color.with_alpha(alpha);
    }
}

pub fn sync_z_from_layer_orders(query: Query<(&mut Transform, &ScratchSprite)>, layer_orders: Res<LayerOrders>) -> () {
    for (mut transform, tag) in query.into_iter() {
        let order = layer_orders.get(tag.target_id.clone());
        transform.translation.z = (order as f32);
    }
}

pub fn build_app(project_path: Arc<str>) -> App {
    let mut app = App::new();
    app.add_plugins(DefaultPlugins);
    app.insert_resource(ProjectPath { path: project_path.clone().clone() });
    app.add_systems(Startup, (spawn_camera, spawn_pen_canvas, setup_scratch_project));
    app.add_systems(Update, ((sync_keyboard_state, sync_mouse_state, sync_scratch_timer, check_key_press_hats, check_greater_than_hats, check_touching_object_hats, check_click_hats, check_backdrop_switch_hats, handle_ask_text_input, run_pending_threads, handle_sprite_dragging, draw_pen_marks, draw_stamps, play_queued_sounds, spawn_pending_clones, despawn_pending_clones).chain(), (sync_transforms_from_positions, sync_visibility_and_size_from_looks_states, sync_costume_from_looks_states, sync_ghost_effect_from_looks_states, sync_z_from_layer_orders, sync_speech_bubbles, sync_variable_watchers, sync_reporter_watchers, sync_list_watchers, sync_ask_ui).chain(), compose_scene_for_touching).chain());
    app
}

pub fn run_game(project_path: Arc<str>) -> () {
    build_app(project_path.clone().clone()).run();
}

fn main() -> () {
    let argv = std::env::args().map(|s| Arc::<str>::from(s)).collect::<Vec<_>>();
    let path = {
    if ((argv.len() as isize) > 1) {
        argv[(1) as usize].clone()
    } else {
        Arc::<str>::from("assets/Fibonacci_1.sb3")
    }
};
    run_game(Arc::<str>::from(path.to_string()));
}

pub fn stage_var_value(path: Arc<str>, vars: Vars, var_name: Arc<str>) -> Arc<str> {
    if let Some(project) = Sb3Project::load_json_for_boring(path.clone()) {
        let var_id = find_stage_var_id(project, var_name.clone().clone());
        let value = vars.get(var_id.clone(), Arc::<str>::from(""));
        Arc::<str>::from(Arc::<str>::from(format!("{}", value).as_str()))
    } else {
        Arc::<str>::from("")
    }
}

pub fn position_value(positions: Positions, target_name: Arc<str>, axis: Arc<str>) -> Arc<str> {
    let p = positions.get(target_name.clone());
    if (axis == Arc::<str>::from("x")) {
        Arc::<str>::from(Arc::<str>::from(format!("{}", p.x).as_str()))
    } else if (axis == Arc::<str>::from("y")) {
        Arc::<str>::from(Arc::<str>::from(format!("{}", p.y).as_str()))
    } else {
        Arc::<str>::from(Arc::<str>::from(format!("{}", p.direction).as_str()))
    }
}

pub fn set_position_value(mut positions: &mut Positions, target_name: Arc<str>, x: f32, y: f32) -> () {
    let current = (*positions).get(target_name.clone());
    (*positions).set(target_name.clone(), Position { x: x, y: y, direction: current.direction });
}


