#[derive(Debug, Clone, serde::Serialize, serde::Deserialize)]
#[serde(untagged)]
enum JVal {
    JNull,
    JBool(bool),
    JNum(f64),
    JStr(Arc<str>),
    JArr(Vec<JVal>),
    JObj(HashMap<Arc<str>, JVal>),
}

impl std::fmt::Display for JVal {
    fn fmt(&self, f: &mut std::fmt::Formatter) -> std::fmt::Result {
        write!(f, "{:?}", self)
    }
}

impl JVal {
    fn as_str(&self) -> Option<Arc<str>> {
        match self.clone() {
            JVal::JStr(s) => {
                Some(s.clone())
            }
            _ => {
                None
            }
        }
    }

    fn as_bool(&self) -> Option<bool> {
        match self.clone() {
            JVal::JBool(b) => {
                Some(b.clone())
            }
            _ => {
                None
            }
        }
    }

    fn as_arr(&self) -> Option<Vec<JVal>> {
        match self.clone() {
            JVal::JArr(a) => {
                Some(a.clone())
            }
            _ => {
                None
            }
        }
    }

    fn as_i64(&self) -> Option<i64> {
        match self.clone() {
            JVal::JNum(n) => {
                Some((n as i64))
            }
            _ => {
                None
            }
        }
    }

    fn as_display_string(&self) -> Option<Arc<str>> {
        match self.clone() {
            JVal::JStr(s) => {
                Some(s.clone())
            }
            JVal::JNum(n) => {
                Some(Arc::<str>::from(Arc::<str>::from(format!("{}", n).as_str())))
            }
            JVal::JBool(b) => {
                Some(Arc::<str>::from(Arc::<str>::from(format!("{}", b).as_str())))
            }
            _ => {
                None
            }
        }
    }

}

fn jval_display_at(items: &Vec<JVal>, idx: isize) -> Option<Arc<str>> {
    if (idx < (items.len() as isize)) {
        items[(idx) as usize].as_display_string()
    } else {
        None
    }
}

