fn aabb_overlap(x1: f32, y1: f32, half_w1: f32, half_h1: f32, x2: f32, y2: f32, half_w2: f32, half_h2: f32) -> bool {
    let dx = {
    if (x1 > x2) {
        (x1 - x2)
    } else {
        (x2 - x1)
    }
};
    let dy = {
    if (y1 > y2) {
        (y1 - y2)
    } else {
        (y2 - y1)
    }
};
    ((dx < (half_w1 + half_w2)) && (dy < (half_h1 + half_h2)))
}

