#[derive(Debug, Clone, PartialEq)]
struct PenColor {
    pub r: f32,
    pub g: f32,
    pub b: f32,
    pub a: f32,
}

impl std::fmt::Display for PenColor {
    fn fmt(&self, f: &mut std::fmt::Formatter) -> std::fmt::Result {
        write!(f, "{:?}", self)
    }
}

impl PenColor {
}

fn pen_color_of(s: &PenState) -> PenColor {
    let h = ((s.hue * 3.6) % 360.0);
    let sat = clamp01((s.saturation / 100.0));
    let v = clamp01((s.brightness / 100.0));
    let i = (((h / 60.0) as f32).floor() as isize);
    let f = ((h / 60.0) - (i as f32));
    let p = (v * (1.0 - sat));
    let q = (v * (1.0 - (sat * f)));
    let t = (v * (1.0 - (sat * (1.0 - f))));
    let mut r = v;
    let mut g = t;
    let mut b = p;
    if (i == 1) {
        r = q;
        g = v.clone();
        b = p;
    } else if (i == 2) {
        r = p;
        g = v.clone();
        b = t;
    } else if (i == 3) {
        r = p;
        g = q;
        b = v.clone();
    } else if (i == 4) {
        r = t;
        g = p;
        b = v.clone();
    } else if (i == 5) {
        r = v.clone();
        g = p;
        b = q;
    }
    let alpha = (1.0 - (s.transparency / 100.0));
    PenColor { r: r, g: g, b: b, a: alpha }
}

fn clamp01(v: f32) -> f32 {
    if (v < 0.0) {
        0.0
    } else if (v > 1.0) {
        1.0
    } else {
        v.clone()
    }
}

fn hex_digit_value(c: Arc<str>) -> isize {
    if (c == Arc::<str>::from("0")) {
        0
    } else if (c == Arc::<str>::from("1")) {
        1
    } else if (c == Arc::<str>::from("2")) {
        2
    } else if (c == Arc::<str>::from("3")) {
        3
    } else if (c == Arc::<str>::from("4")) {
        4
    } else if (c == Arc::<str>::from("5")) {
        5
    } else if (c == Arc::<str>::from("6")) {
        6
    } else if (c == Arc::<str>::from("7")) {
        7
    } else if (c == Arc::<str>::from("8")) {
        8
    } else if (c == Arc::<str>::from("9")) {
        9
    } else if ((c == Arc::<str>::from("a")) || (c == Arc::<str>::from("A"))) {
        10
    } else if ((c == Arc::<str>::from("b")) || (c == Arc::<str>::from("B"))) {
        11
    } else if ((c == Arc::<str>::from("c")) || (c == Arc::<str>::from("C"))) {
        12
    } else if ((c == Arc::<str>::from("d")) || (c == Arc::<str>::from("D"))) {
        13
    } else if ((c == Arc::<str>::from("e")) || (c == Arc::<str>::from("E"))) {
        14
    } else if ((c == Arc::<str>::from("f")) || (c == Arc::<str>::from("F"))) {
        15
    } else {
        0
    }
}

fn hex_byte_value(hi: Arc<str>, lo: Arc<str>) -> isize {
    ((hex_digit_value(hi.clone().clone()) * 16) + hex_digit_value(lo.clone().clone()))
}

