impl SoundQueue {
    fn get_scene_pixel(&self, x: isize, y: isize) -> PenColor {
        if ((((x < 0) || (x >= 480)) || (y < 0)) || (y >= 360)) {
            PenColor { r: 0.0, g: 0.0, b: 0.0, a: 0.0 }
        } else {
            let i = ((y.wrapping_mul((480 as isize)) as isize).wrapping_add(x) * 4);
            let byte_r = self.scene_composite[(i) as usize].clone();
            let byte_g = self.scene_composite[((i + 1)) as usize].clone();
            let byte_b = self.scene_composite[((i + 2)) as usize].clone();
            let byte_a = self.scene_composite[((i + 3)) as usize].clone();
            PenColor { r: ((byte_r as f32) / 255.0), g: ((byte_g as f32) / 255.0), b: ((byte_b as f32) / 255.0), a: ((byte_a as f32) / 255.0) }
        }
    }

    fn get_sound_duration(&self, target_id: Arc<str>, sound_name: Arc<str>) -> f32 {
        let by_name: HashMap<Arc<str>, f32> = self.sound_durations.get(&*target_id).cloned().unwrap_or_else(|| HashMap::new());
        by_name.get(&*sound_name).cloned().unwrap_or_else(|| 0.0)
    }

    fn get_volume(&self, target_id: Arc<str>) -> f32 {
        self.volumes.get(&*target_id).cloned().unwrap_or_else(|| 100.0)
    }

    fn set_volume(&mut self, target_id: Arc<str>, v: f32) -> () {
        self.volumes.insert(target_id.clone(), v.clone());
    }

    fn remove_volume(&mut self, target_id: Arc<str>) -> () {
        self.volumes.remove(&*target_id);
    }

    fn get_rotation_style(&self, target_id: Arc<str>) -> Arc<str> {
        self.rotation_styles.get(&*target_id).cloned().unwrap_or_else(|| Arc::<str>::from("all around"))
    }

    fn set_rotation_style(&mut self, target_id: Arc<str>, style: Arc<str>) -> () {
        self.rotation_styles.insert(target_id.clone(), style.clone());
    }

    fn remove_rotation_style(&mut self, target_id: Arc<str>) -> () {
        self.rotation_styles.remove(&*target_id);
    }

    fn get_draggable(&self, target_id: Arc<str>) -> bool {
        self.draggable.get(&*target_id).cloned().unwrap_or_else(|| false)
    }

    fn set_draggable(&mut self, target_id: Arc<str>, v: bool) -> () {
        self.draggable.insert(target_id.clone(), v.clone());
    }

    fn remove_draggable(&mut self, target_id: Arc<str>) -> () {
        self.draggable.remove(&*target_id);
    }

    fn get_pen_state(&self, target_id: Arc<str>) -> PenState {
        self.pen_states.get(&*target_id).cloned().unwrap_or_else(|| default_pen_state())
    }

    fn set_pen_state(&mut self, target_id: Arc<str>, s: PenState) -> () {
        self.pen_states.insert(target_id.clone(), s.clone());
    }

    fn remove_pen_state(&mut self, target_id: Arc<str>) -> () {
        self.pen_states.remove(&*target_id);
    }

    fn get_pitch(&self, target_id: Arc<str>) -> f32 {
        self.pitches.get(&*target_id).cloned().unwrap_or_else(|| 0.0)
    }

    fn set_pitch(&mut self, target_id: Arc<str>, v: f32) -> () {
        self.pitches.insert(target_id.clone(), v.clone());
    }

    fn remove_pitch(&mut self, target_id: Arc<str>) -> () {
        self.pitches.remove(&*target_id);
    }

    fn get_pan(&self, target_id: Arc<str>) -> f32 {
        self.pans.get(&*target_id).cloned().unwrap_or_else(|| 0.0)
    }

    fn set_pan(&mut self, target_id: Arc<str>, v: f32) -> () {
        self.pans.insert(target_id.clone(), v.clone());
    }

    fn remove_pan(&mut self, target_id: Arc<str>) -> () {
        self.pans.remove(&*target_id);
    }

    fn instance_type_of(&self, instance_id: Arc<str>) -> Arc<str> {
        self.instance_types.get(&*instance_id).cloned().unwrap_or_else(|| instance_id.clone())
    }

    fn set_instance_type(&mut self, instance_id: Arc<str>, origin_name: Arc<str>) -> () {
        self.instance_types.insert(instance_id.clone(), origin_name.clone());
    }

    fn remove_instance_type(&mut self, instance_id: Arc<str>) -> () {
        self.instance_types.remove(&*instance_id);
    }

}

fn instances_of(instance_types: &HashMap<Arc<str>, Arc<str>>, origin: Arc<str>) -> Vec<Arc<str>> {
    let mut result = vec![];
    for (id, v) in instance_types.into_iter() {
        if (v.clone() == origin) {
            result.push(id.clone());
        }
    }
    result
}

