fn list_watcher_display_string(lists: Lists, list_id: Arc<str>) -> Arc<str> {
    let items = lists.get(list_id.clone(), lists.owner_of(list_id.clone()));
    let mut all_single_char = true;
    for item in items.iter().cloned() {
        match item {
            ScratchValue::Str(s) => {
                if ((s.len() as isize) != 1) {
                    all_single_char = false;
                }
            }
            ScratchValue::Num(n) => {
                all_single_char = false;
            }
            ScratchValue::Bool(b) => {
                all_single_char = false;
            }
        }
    }
    let sep = {
    if all_single_char {
        Arc::<str>::from("")
    } else {
        Arc::<str>::from("\n")
    }
};
    let mut result: Arc<str> = Arc::<str>::from("");
    let mut first = true;
    for item in items.iter().cloned() {
        if first {
            result = Arc::<str>::from(Arc::<str>::from(format!("{}", item).as_str()));
            first = false;
        } else {
            result = Arc::<str>::from(Arc::<str>::from(format!("{}{}{}", result, sep, item).as_str()));
        }
    }
    result.clone()
}

