use std::fs::File;

use std::io::Read;

use std::path::Path;

use zip::ZipArchive;

use zip::read::ZipFile;

use resvg::usvg::{Options, Tree};

use resvg::usvg::fontdb::Database;

use resvg::tiny_skia::Pixmap;

fn read_zip_entry_bytes(sb3Path: Arc<str>, entryFilename: Arc<str>) -> Option<Vec<u8>> {
    let fileOpt = File::open(sb3Path.as_ref()).ok();
    let Some(file) = (fileOpt) else {
        return None;
    };
    let archiveOpt = ZipArchive::new(file).ok();
    let Some(archiveFixed) = (archiveOpt) else {
        return None;
    };
    let mut archive = archiveFixed;
    let entryCount = ZipArchive::len(&archive);
    let mut foundName: Option<Arc<str>> = None;
    let mut i = (0i64 as usize);
    while (i < entryCount) {
        let indexedOpt = ZipArchive::by_index(&mut archive, i).ok();
        if let Some(indexed) = indexedOpt {
            let rawName = indexed.name();
            let nameStr: Arc<str> = Arc::<str>::from(Arc::<str>::from(format!("{}", rawName).as_str()));
            if zip_entry_matches(Arc::<str>::from(nameStr.clone().to_string()), Arc::<str>::from(entryFilename.clone().to_string())) {
                foundName = Some(nameStr.clone());
            }
        }
        i += (1i64 as usize);
    }
    let Some(entryName) = (foundName) else {
        return None;
    };
    let entryOpt = ZipArchive::by_name(&mut archive, &entryName).ok();
    let Some(entryFixed) = (entryOpt) else {
        return None;
    };
    let mut entry = entryFixed;
    if (entry.size() > MAX_ZIP_ENTRY_BYTES) {
        return None;
    }
    let mut buf: Vec<u8> = vec![];
    let bytesReadOpt = ZipFile::read_to_end(&mut entry, &mut buf).ok();
    let Some(bytesRead) = (bytesReadOpt) else {
        return None;
    };
    Some(buf)
}

pub fn rasterize_svg_to_png(svgBytes: &Vec<u8>) -> Option<Vec<u8>> {
    let mut fonts = Database::new();
    fonts.load_system_fonts();
    let mut opts = Options::default();
    opts.fontdb = fonts.into();
    let treeOpt = Tree::from_data(&svgBytes, &opts).ok();
    let Some(tree) = (treeOpt) else {
        return None;
    };
    let size = tree.size();
    let width = (size.width().ceil() as u32);
    let height = (size.height().ceil() as u32);
    let Some(pixmap) = (Pixmap::new(width.max(1), height.max(1))) else {
        return None;
    };
    let mut pixmap2 = pixmap;
    resvg::render(&tree, resvg::tiny_skia::Transform::default(), &mut pixmap2.as_mut());
    let pngOpt = pixmap2.encode_png().ok();
    let Some(png) = (pngOpt) else {
        return None;
    };
    Some(png)
}

fn is_safe_asset_id(s: Arc<str>) -> bool {
    if ((s.len() as isize) == 0) {
        return false;
    }
    let mut chars = s.chars().map(|c| Arc::<str>::from(c.to_string())).collect::<Vec<Arc<str>>>();
    for c in chars.iter().cloned() {
        let lowered = Arc::<str>::from(Arc::<str>::from(format!("{}", c).as_str()).to_lowercase().as_str());
        let is_digit = ((((((((((lowered == Arc::<str>::from("0")) || (lowered == Arc::<str>::from("1"))) || (lowered == Arc::<str>::from("2"))) || (lowered == Arc::<str>::from("3"))) || (lowered == Arc::<str>::from("4"))) || (lowered == Arc::<str>::from("5"))) || (lowered == Arc::<str>::from("6"))) || (lowered == Arc::<str>::from("7"))) || (lowered == Arc::<str>::from("8"))) || (lowered == Arc::<str>::from("9")));
        let is_letter = ((((((((((((((((((((((((((lowered == Arc::<str>::from("a")) || (lowered == Arc::<str>::from("b"))) || (lowered == Arc::<str>::from("c"))) || (lowered == Arc::<str>::from("d"))) || (lowered == Arc::<str>::from("e"))) || (lowered == Arc::<str>::from("f"))) || (lowered == Arc::<str>::from("g"))) || (lowered == Arc::<str>::from("h"))) || (lowered == Arc::<str>::from("i"))) || (lowered == Arc::<str>::from("j"))) || (lowered == Arc::<str>::from("k"))) || (lowered == Arc::<str>::from("l"))) || (lowered == Arc::<str>::from("m"))) || (lowered == Arc::<str>::from("n"))) || (lowered == Arc::<str>::from("o"))) || (lowered == Arc::<str>::from("p"))) || (lowered == Arc::<str>::from("q"))) || (lowered == Arc::<str>::from("r"))) || (lowered == Arc::<str>::from("s"))) || (lowered == Arc::<str>::from("t"))) || (lowered == Arc::<str>::from("u"))) || (lowered == Arc::<str>::from("v"))) || (lowered == Arc::<str>::from("w"))) || (lowered == Arc::<str>::from("x"))) || (lowered == Arc::<str>::from("y"))) || (lowered == Arc::<str>::from("z")));
        if (!(is_digit || is_letter)) {
            return false;
        }
    }
    true
}

