fn extract_costume_bytes_to_temp_file(sb3Path: Arc<str>, costume: &Sb3Costume) -> Option<Arc<str>> {
    if (!is_safe_asset_id(Arc::<str>::from(costume.asset_id.clone().clone().to_string()))) {
        return None;
    }
    let Some(checked_extension) = (costume_extension_for_format(Arc::<str>::from(Arc::<str>::from(format!("{}", costume.data_format.clone()).as_str())))) else {
        return None;
    };
    let rawOpt = read_zip_entry_bytes(Arc::<str>::from(sb3Path.clone().to_string()), Arc::<str>::from(costume.md5ext.clone().to_string()));
    let Some(rawBytes) = (rawOpt) else {
        return None;
    };
    let mut outBytes = vec![];
    let mut extension: Arc<str> = Arc::<str>::from("");
    if (Arc::<str>::from(format!("{}", costume.data_format.clone()).as_str()) == Arc::<str>::from("svg")) {
        let pngOpt = rasterize_svg_to_png(&rawBytes);
        let Some(png) = (pngOpt) else {
            return None;
        };
        outBytes = png.clone();
        extension = Arc::<str>::from("png");
    } else {
        outBytes = rawBytes.clone();
        extension = checked_extension.clone();
    }
    let Some(assetsDir) = (Path::new(sb3Path.as_ref()).parent()) else {
        return None;
    };
    let cacheDir = Path::join(&assetsDir, &".costume_cache");
    let createOpt = std::fs::create_dir_all(cacheDir.clone()).ok();
    let Some(created) = (createOpt) else {
        return None;
    };
    let fileName: Arc<str> = Arc::<str>::from(Arc::<str>::from(format!("{}.{}", costume.asset_id.clone(), extension).as_str()));
    let fullPath = Path::join(&cacheDir, &fileName.as_ref());
    let writeOpt = std::fs::write(fullPath, outBytes).ok();
    let Some(wrote) = (writeOpt) else {
        return None;
    };
    Some(Arc::<str>::from(Arc::<str>::from(format!(".costume_cache/{}", fileName).as_str())))
}

pub fn extract_current_costume_to_temp_file(sb3Path: Arc<str>, targetName: Arc<str>) -> Option<Arc<str>> {
    let Some(project) = (Sb3Project::load_for_boring(sb3Path.clone())) else {
        return None;
    };
    let Some(costume) = (find_target_costume(project, targetName.clone().clone())) else {
        return None;
    };
    extract_costume_bytes_to_temp_file(sb3Path.clone().clone(), &costume)
}

pub fn extract_costume_at_index_to_temp_file(sb3Path: Arc<str>, targetName: Arc<str>, idx: isize) -> Option<Arc<str>> {
    let Some(project) = (Sb3Project::load_for_boring(sb3Path.clone())) else {
        return None;
    };
    let Some(costume) = (find_target_costume_at_index(project, targetName.clone().clone(), idx.clone())) else {
        return None;
    };
    extract_costume_bytes_to_temp_file(sb3Path.clone().clone(), &costume)
}

fn png_dimensions(bytes: &Vec<u8>) -> Option<(u32, u32)> {
    if ((bytes.len() as isize) < 24) {
        return None;
    }
    if ((((bytes[(0) as usize].clone() != 137) || (bytes[(1) as usize].clone() != 80)) || (bytes[(2) as usize].clone() != 78)) || (bytes[(3) as usize].clone() != 71)) {
        return None;
    }
    let width = (((((bytes[(16) as usize].clone() as u32) * 16777216) + ((bytes[(17) as usize].clone() as u32) * 65536)) + ((bytes[(18) as usize].clone() as u32) * 256)) + (bytes[(19) as usize].clone() as u32));
    let height = (((((bytes[(20) as usize].clone() as u32) * 16777216) + ((bytes[(21) as usize].clone() as u32) * 65536)) + ((bytes[(22) as usize].clone() as u32) * 256)) + (bytes[(23) as usize].clone() as u32));
    Some((width, height))
}

fn costume_pixel_dims(sb3Path: Arc<str>, targetName: Arc<str>, idx: isize) -> Option<CostumeDim> {
    let Some(cachePath) = (extract_costume_at_index_to_temp_file(Arc::<str>::from(sb3Path.clone().to_string()), Arc::<str>::from(targetName.clone().to_string()), idx.clone())) else {
        return None;
    };
    let Some(assetsDir) = (Path::new(sb3Path.as_ref()).parent()) else {
        return None;
    };
    let fullPath = Path::join(&assetsDir, &cachePath.as_ref());
    let bytesOpt = std::fs::read(fullPath).ok();
    let Some(bytes) = (bytesOpt) else {
        return None;
    };
    let Some(dims_tuple) = (png_dimensions(&bytes)) else {
        return None;
    };
    let (w, h) = dims_tuple;
    Some(CostumeDim { width: (w as f32), height: (h as f32) })
}

pub fn build_target_costume_dims(sb3Path: Arc<str>, project: Sb3Project) -> TargetCostumeDims {
    let mut table = HashMap::new();
    for target in project.targets.iter().cloned() {
        let target_id: Arc<str> = Arc::<str>::from(Arc::<str>::from(format!("{}", target.name_string()).as_str()));
        let mut dims = vec![];
        let mut i = 0;
        while (i < (target.costumes.len() as isize)) {
            let resolution = (target.costumes[(i) as usize].clone().bitmap_resolution.unwrap_or_else(|| 1.0) as f32);
            if let Some(raw) = costume_pixel_dims(Arc::<str>::from(sb3Path.clone().to_string()), Arc::<str>::from(target_id.clone().to_string()), i) {
                dims.push(CostumeDim { width: (raw.width / resolution), height: (raw.height / resolution) });
            } else {
                dims.push(CostumeDim { width: 40.0, height: 40.0 });
            }
            i += 1;
        }
        table.insert(target_id.clone(), dims);
    }
    TargetCostumeDims { table: table }
}

fn find_target_sound(project: Sb3Project, targetName: Arc<str>, soundName: Arc<str>) -> Option<Sb3Sound> {
    for target in project.targets.iter().cloned() {
        if target.name_matches(targetName.clone()) {
            let Some(sound) = (target.sound_by_name(soundName.clone())) else {
                return None;
            };
            return Some(sound.clone());
        }
    }
    None
}

pub fn extract_sound_to_temp_file(sb3Path: Arc<str>, targetName: Arc<str>, soundName: Arc<str>) -> Option<Arc<str>> {
    let Some(project) = (Sb3Project::load_for_boring(sb3Path.clone())) else {
        return None;
    };
    let Some(sound) = (find_target_sound(project, targetName.clone().clone(), soundName.clone().clone())) else {
        return None;
    };
    if (!is_safe_asset_id(Arc::<str>::from(sound.asset_id.clone().clone().to_string()))) {
        return None;
    }
    let Some(checked_extension) = (sound_extension_for_format(Arc::<str>::from(Arc::<str>::from(format!("{}", sound.data_format.clone()).as_str())))) else {
        return None;
    };
    let rawOpt = read_zip_entry_bytes(Arc::<str>::from(sb3Path.clone().to_string()), Arc::<str>::from(sound.md5ext.clone().to_string()));
    let Some(rawBytes) = (rawOpt) else {
        return None;
    };
    let Some(assetsDir) = (Path::new(sb3Path.as_ref()).parent()) else {
        return None;
    };
    let cacheDir = Path::join(&assetsDir, &".sound_cache");
    let createOpt = std::fs::create_dir_all(cacheDir.clone()).ok();
    let Some(created) = (createOpt) else {
        return None;
    };
    let fileName: Arc<str> = Arc::<str>::from(Arc::<str>::from(format!("{}.{}", sound.asset_id.clone(), checked_extension).as_str()));
    let fullPath = Path::join(&cacheDir, &fileName.as_ref());
    let writeOpt = std::fs::write(fullPath, rawBytes).ok();
    let Some(wrote) = (writeOpt) else {
        return None;
    };
    Some(Arc::<str>::from(Arc::<str>::from(format!(".sound_cache/{}", fileName).as_str())))
}


